package com.example.smartexpenseanalyzer.service;
import com.example.smartexpenseanalyzer.model.*; import com.example.smartexpenseanalyzer.repository.*; import jakarta.servlet.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.*; import java.math.*; import java.time.*; import java.util.stream.*;
@org.springframework.stereotype.Component public class ApiFacade {
 private final AppUserRepository users; private final ExpenseRepository expenses; private final TripRepository trips; private final PasswordEncoder encoder; private final com.example.smartexpenseanalyzer.service.AppUserDetailsService userService; private final com.example.smartexpenseanalyzer.service.ExpenseService expenseService; private final com.example.smartexpenseanalyzer.service.TripService tripService; private final com.example.smartexpenseanalyzer.service.DashboardService dashboardService; private final AdminProfileService adminService;
 public ApiFacade(AppUserRepository u,ExpenseRepository e,TripRepository t,PasswordEncoder p,com.example.smartexpenseanalyzer.service.AppUserDetailsService us,com.example.smartexpenseanalyzer.service.ExpenseService es,com.example.smartexpenseanalyzer.service.TripService ts,com.example.smartexpenseanalyzer.service.DashboardService ds,AdminProfileService ads){users=u;expenses=e;trips=t;encoder=p;userService=us;expenseService=es;tripService=ts;dashboardService=ds;adminService=ads;}
 private AppUser me(HttpSession s){return userService.find((Long)s.getAttribute("uid")).orElseThrow();}
 private Map<String,Object> safe(AppUser u){return Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role,"budget",u.budget);}
 public ResponseEntity<?> register(Map<String,String> x,HttpSession s){String email=x.getOrDefault("email","").trim().toLowerCase(); String name=x.getOrDefault("name","").trim(); String pw=x.getOrDefault("password",""); if(name.isBlank()||(email.indexOf('@')<1||email.lastIndexOf('.')<email.indexOf('@')+2||email.endsWith("."))||pw.length()<8)return ResponseEntity.badRequest().body(Map.of("error","Enter a name, valid email and password of at least 8 characters.")); AppUser u=userService.register(name,email,pw).orElse(null);if(u==null)return ResponseEntity.badRequest().body(Map.of("error","An account with that email already exists."));s.setAttribute("uid",u.id);s.setAttribute("role",u.role);return ResponseEntity.ok(safe(u));}
 public ResponseEntity<?> login(Map<String,String>x,HttpSession s){AppUser u=userService.authenticate(x.getOrDefault("email","").trim(),x.getOrDefault("password","")).orElse(null); if(u==null)return ResponseEntity.status(401).body(Map.of("error","Email or password is incorrect."));s.setAttribute("uid",u.id);s.setAttribute("role",u.role);return ResponseEntity.ok(safe(u));}
 public Map<String,String> logout(HttpSession s){s.invalidate();return Map.of("message","Signed out");}
 public Map<String,Object> current(HttpSession s){return safe(me(s));}
 public List<Map<String,Object>> list(HttpSession s){AppUser u=me(s);return expenseService.forUser(u).stream().map(this::expenseMap).toList();}
 private Map<String,Object> expenseMap(Expense e){return Map.of("id",e.id,"category",e.category,"description",e.description,"amount",e.amount,"date",e.date,"tripId",e.trip==null?0:e.trip.id,"tripName",e.trip==null?"":e.trip.name);}
 public ResponseEntity<?> add(Map<String,String>x,HttpSession s){return saveExpense(null,x,s);}
 public ResponseEntity<?> edit(Long id,Map<String,String>x,HttpSession s){return saveExpense(id,x,s);}
 private ResponseEntity<?> saveExpense(Long id,Map<String,String>x,HttpSession s){try{AppUser u=me(s);BigDecimal amount=new BigDecimal(x.getOrDefault("amount","0"));String category=x.getOrDefault("category","").trim(),desc=x.getOrDefault("description","").trim();expenseService.validateAmount(amount);if(category.isBlank()||desc.isBlank())throw new IllegalArgumentException();Expense e=id==null?new Expense():expenseService.findOwned(id,u).orElseThrow();e.user=u;e.amount=amount;e.category=category;e.description=desc;e.date=LocalDate.parse(x.getOrDefault("date",LocalDate.now().toString()));long tid=Long.parseLong(x.getOrDefault("tripId","0"));e.trip=tid==0?null:tripService.findOwned(tid,u).orElseThrow();return ResponseEntity.ok(expenseMap(expenseService.save(e)));}catch(Exception ex){return ResponseEntity.badRequest().body(Map.of("error","Check the amount, category, description, date and trip."));}}
 public Map<String,String> delete(Long id,HttpSession s){expenseService.delete(expenseService.findOwned(id,me(s)).orElseThrow());return Map.of("message","Expense deleted");}
 public Map<String,Object> dashboard(HttpSession s){AppUser u=me(s);return dashboardService.summarize(u,expenseService.forUser(u));}
 public Map<String,Object> budget(Map<String,String>x,HttpSession s){AppUser u=me(s);BigDecimal v=new BigDecimal(x.getOrDefault("budget","0"));if(v.signum()<0)throw new IllegalArgumentException("Budget cannot be negative");u.budget=v;userService.save(u);return safe(u);}
 public List<Map<String,Object>> getTrips(HttpSession s){return tripService.forUser(me(s)).stream().map(t->Map.<String,Object>of("id",t.id,"name",t.name,"destination",Objects.toString(t.destination,""),"startDate",Objects.toString(t.startDate,""),"endDate",Objects.toString(t.endDate,""))).toList();}
 public Map<String,Object> addTrip(Map<String,String>x,HttpSession s){Trip t=new Trip();t.user=me(s);t.name=x.getOrDefault("name","").trim();if(t.name.isBlank())throw new IllegalArgumentException("Trip name required");t.destination=x.get("destination");if(x.containsKey("startDate")&&!x.get("startDate").isBlank())t.startDate=LocalDate.parse(x.get("startDate"));if(x.containsKey("endDate")&&!x.get("endDate").isBlank())t.endDate=LocalDate.parse(x.get("endDate"));t=tripService.save(t);return Map.of("id",t.id,"name",t.name);}
 public Map<String,String> delTrip(Long id,HttpSession s){Trip t=tripService.findOwned(id,me(s)).orElseThrow();List<Expense> linked=expenses.findByUserOrderByDateDesc(t.user).stream().filter(e->e.trip!=null&&e.trip.id.equals(id)).toList();linked.forEach(e->e.trip=null);expenseService.saveAll(linked);tripService.delete(t);return Map.of("message","Trip deleted");}
 public Map<String,Object> admin(){return adminService.overview();}
 public List<Map<String,Object>> adminUsers(){return userService.all().stream().map(this::safe).toList();}
 public Map<String,Object> role(Long id,Map<String,String>x){String r=x.getOrDefault("role","USER");if(!List.of("ADMIN","USER").contains(r))throw new IllegalArgumentException();return safe(adminService.updateRole(id,r));}
 public Map<String,String> deleteUser(Long id,HttpSession s){if(id.equals(me(s).id))throw new IllegalArgumentException("Cannot delete your own account");AppUser u=userService.find(id).orElseThrow();adminService.removeProfile(id);expenseService.deleteAll(expenseService.forUser(u));tripService.deleteAll(tripService.forUser(u));userService.delete(u);return Map.of("message","User deleted");}
}
